{"command": "cd /workspace && cat > work/ft2lib.py <<'EOF'
import json, subprocess, base64
import numpy as np, wave

def call(tool, **kw):
    p = subprocess.run(['ft2','call',tool,json.dumps(kw)],capture_output=True,text=True)
    if p.returncode!=0:
        raise RuntimeError(p.stderr[:2000])
    out = json.loads(p.stdout)
    if out.get('isError'): raise RuntimeError(out)
    c = out['content'][0]['text']
    try: return json.loads(c)
    except Exception: return c

def batch(calls, path='/tmp/b.json'):
    with open(path,'w') as f: json.dump(calls,f)
    p = subprocess.run(['ft2','batch',path],capture_output=True,text=True)
    if p.returncode!=0: raise RuntimeError(p.stdout[-3000:]+p.stderr[-3000:])
    return p.stdout

def load_wav(path):
    w=wave.open(path)
    n=w.getnchannels()
    d=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).reshape(-1,n)
    return d, w.getframerate()

def pcm_b64(x, encoding='float32'):
    if encoding=='float32':
        x=np.asarray(x,dtype=np.float32)
    else:
        x=np.clip(np.asarray(x),-32768,32767).astype(np.int16)
    return base64.b64encode(x.tobytes()).decode()

def freq_of(sig, sr, start, n):
    """crude zero crossing / autocorrelation freq"""
    s=sig[start:start+n].astype(float)
    s=s-s.mean()
    ac=np.correlate(s,s,'full')[len(s)-1:]
    # find first peak after min lag
    lo=int(sr/4000); hi=int(sr/40)
    seg=ac[lo:hi]
    return sr/(lo+int(np.argmax(seg)))
